window.kbPageData["views/entry/k-ba21811591ff4d33"] = {"key":"entry/k-ba21811591ff4d33","state":{"route":"entry/k-ba21811591ff4d33"},"node":{"id":"k-ba21811591ff4d33","mode":"k","title":"实体经济","type":"概念与词义","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":["国考 2023 地市级 行测#4"],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"tags":{"专题":["industry"],"主类":["概念与词义"],"出处性质":["机构注释"],"学科":["政治理论","经济"],"来源主题":["产业、科技与对外开放"],"资料类别":["非时政"]},"directorySummary":"实体经济涵盖物质产品生产以及提供实际服务的经济活动，制造业是其中的重要组成部分。《习近平经济思想学习纲要》把大力发展制造业和实体经济概括为我国经济发展的主要着力点。","review":{"definition":"实体经济涵盖物质产品生产以及提供实际服务的经济活动，制造业是其中的重要组成部分。《习近平经济思想学习纲要》把大力发展制造业和实体经济概括为我国经济发展的主要着力点。","explanation":"⑤沿用《习近平经济思想学习纲要》的表述，并提制造业和实体经济，突出制造业在实体经济中的地位。这里对应的定位是“主要着力点”，所以⑤计入正确项。","references":[],"evidence":"大力发展制造业和实体经济是我国经济发展的主要着力点","disposition":"独立词条","basis":"据原题和解析编释。"},"sources":[{"id":"d28abd67bac9d0d3","label":"实体经济","topic":"产业、科技与对外开放","category":"非时政","text":"2.实体经济\n实体经济指物质的、精神的产品和服务的生产、流通等经济活动，包括农业、工业、交\n通运输业、商业、建筑业等物质生产和服务部门，是国民经济的根基，区别于金融、房地产\n等虚拟经济领域，实体经济是一国经济的立身之本，是财富创造的根本源泉，是国家强盛的\n重要支柱。习近平总书记强调，经济发展任何时候都不能脱实向虚。要处理好实体经济与虚\n拟经济的关系，推动虚拟经济服务于实体经济，促进两者协同发展。","source":{"doc":"6cbfb01fe723bba64b75","first":16,"last":16,"page":16,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{"国考 2023 地市级 行测#4":{"paper":"国考 2023 地市级 行测","n":4,"mod":"常识判断","src":["64bc3a15d27a04e94940.pdf",1],"asrc":["f3ab652d8e31c5bbdabc.pdf",2],"card":"62e6c598bc157bb0c0fe57d0","links":[{"id":"k-ba21811591ff4d33","role":"直接考查","why":"题目要求识别制造业和实体经济在我国经济发展中的着力点定位。"}]}},"terms":{},"references":{},"topics":[{"slug":"industry","title":"产业升级与新质生产力"}],"units":{"k-ba21811591ff4d33":[["国考 2023 地市级 行测#4"]]}};
